import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const{api}=await import('./gta-email-recovery-runtime.mjs');const dir='artifacts/unknown-partnership-calls-20261019';await fs.mkdir(dir,{recursive:true});const out={at:new Date().toISOString()};
for(const path of ['/api/marketing/dialer/twiml','/api/sales/interactions?pending=false']){try{const r=await api(path);out[path]=path.includes('interactions')?{count:r.interactions?.length,sample:r.interactions?.filter(x=>x.event?.source?.includes('partnership_call')).map(x=>({id:x.id,source:x.event.source,from:x.event.sender,to:x.event.recipient,lead:x.lead_id})).slice(0,5)}:r;}catch(e){out[path]={error:e.message}}}
const q=await db('crm_interaction_review_queue',{'event->>source':'eq.partnership_call',order:'received_at.desc',limit:'40'});out.calls=[];for(const r of q){const phone=String(r.event.sender||'').replace(/\D/g,'').slice(-10);if(phone.length!==10)continue;const contacts=await db('market_contacts',{phone:'ilike.*'+phone,select:'id,name',limit:'5'});if(!contacts.length)out.calls.push({id:r.id,at:r.received_at,from:r.event.sender,to:r.event.recipient,leadId:r.lead_id,provenance:r.event.provenance});if(out.calls.length>=3)break;}
const sid=process.env.TWILIO_ACCOUNT_SID?.trim(),token=process.env.TWILIO_AUTH_TOKEN?.trim();if(sid&&token){const base='https://api.twilio.com/2010-04-01/Accounts/'+sid;const headers={Authorization:'Basic '+Buffer.from(sid+':'+token).toString('base64')};const res=await fetch(base+'/Calls.json?To=%2B14374650584&PageSize=5',{headers});const data=await res.json();out.providerCalls=res.ok?data.calls?.map(c=>({sid:c.sid,from:c.from,to:c.to,status:c.status,duration:c.duration})):res.status;}
await fs.writeFile(dir+'/audit.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));
